def count_binary_strings(n: int) -> int:
    """Count binary strings of length n with no consecutive 1s.

    Uses the recurrence:
      dp0[i] = strings of length i ending in 0
      dp1[i] = strings of length i ending in 1
      dp0[i] = dp0[i-1] + dp1[i-1]
      dp1[i] = dp0[i-1]
    Total follows the Fibonacci sequence: f(n) = f(n-1) + f(n-2).
    """
    if n <= 0:
        return 0
    if n == 1:
        return 2
    a, b = 2, 3  # f(1), f(2)
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b


if __name__ == "__main__":
    for i in range(1, 11):
        print(f"n={i}: {count_binary_strings(i)}")
